function BootyRaider.Services.RaidItemCatalog.GetItems(raidName)
    local data = ids[raidName]
    if not data then return nil, "No item catalogue is available for this raid type. Select a supported raid type." end
    local items = {}
    for value in string.gfind(data, "%d+") do table.insert(items, tonumber(value)) end
    return items
